        Long last = values.get(values.size() - 1);
        Long prev = values.get(values.size() - 2);
        if (prev > 0) {
            vo.setGrowthRate((last - prev) * 100.0 / prev);
        } else {
            vo.setGrowthRate(0.0);
        }
    } else {
        vo.setGrowthRate(0.0);
    }

    return vo;
}

