private UserVO convertToVO(RsbtUser entity) {

    }

    private UserVO convertToVO(RsbtUser entity) {
        UserVO vo = new UserVO();
        vo.setGuid(entity.getGuid());
        vo.setUsername(entity.getUsername());
        vo.setName(entity.getName());
        vo.setEmail(entity.getEmail());
        vo.setPhone(entity.getPhone());
        vo.setRoleId(entity.getRoleId());
        vo.setOrgId(entity.getOrgId());
        vo.setStatus(entity.getStatus());

        if (entity.getRoleId() != null) {
            RsbtRole role = roleMapper.selectById(entity.getRoleId());
            if (role != null) {
                vo.setRoleName(role.getName());
            }
        }
        if (entity.getOrgId() != null) {
            RsbtOrganization org = organizationMapper.selectById(entity.getOrgId());
            if (org != null) {
                vo.setOrgName(org.getName());
            }
        }
        return vo;
    }
}

    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain filterChain) throws ServletException, IOException {
        String auth = request.getHeader("Authorization");
        if (StringUtils.hasText(auth) && auth.startsWith("Bearer ")) {
            try {
                String username = jwtUtil.parseUsername(auth.substring(7));
                List<SimpleGrantedAuthority> authorities = userService.getUserAuthorities(username);
                UsernamePasswordAuthenticationToken token = new UsernamePasswordAuthenticationToken(username, null, authorities);
                SecurityContextHolder.getContext().setAuthentication(token);
            } catch (Exception ignored) {
            }
        }
        filterChain.doFilter(request, response);
    }
}

private final SecretKey key = Keys.hmacShaKeyFor(SECRET.getBytes(StandardCharsets.UTF_8));

public String generate(String username) {
    Date now = new Date();
    return Jwts.builder().subject(username).issuedAt(now).expiration(new Date(now.getTime() + EXPIRE)).signWith(key).compact();
}

public String parseUsername(String token) {

    }

    public String parseUsername(String token) {
        Claims claims = Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();
        return claims.getSubject();
    }
}
